import { useState } from "react";

interface UseControlledOpenProps {
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
}

interface UseControlledOpenResult {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  close: () => void;
}

export const useControlledOpen = ({
  open,
  onOpenChange,
}: UseControlledOpenProps): UseControlledOpenResult => {
  const [internalOpen, setInternalOpen] = useState(false);

  // Determine if the component is controlled or uncontrolled
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const setIsOpen = (newOpen: boolean) => {
    if (!isControlled) {
      setInternalOpen(newOpen);
    }
    if (onOpenChange) {
      onOpenChange(newOpen);
    }
  };

  const close = () => setIsOpen(false);

  return { close, isOpen, setIsOpen };
};

"use client";

import * as React from "react";

import { useControlledOpen } from "@/registry/hooks/useControlledOpen";
import { useKitzeUI } from "@/registry/new-york/kitze-ui-context/KitzeUIContext";
import { ResponsiveSelectBottomDrawerMenu } from "@/registry/new-york/responsive-select-bottom-drawer-menu/ResponsiveSelectBottomDrawerMenu";
import { SimpleSelectNative } from "@/registry/new-york/simple-select/SimpleSelectNative";
import { SimpleSelectPopover } from "@/registry/new-york/simple-select/SimpleSelectPopover";
import { SimpleSelectTrigger } from "@/registry/new-york/simple-select/SimpleSelectTrigger";
import type * as SimpleSelectTypesModule from "@/registry/new-york/simple-select/SimpleSelectTypes";

export type SelectMobileViewType = SimpleSelectTypesModule.SelectMobileViewType;
export type SimpleSelectOption = SimpleSelectTypesModule.SimpleSelectOption;
export type SimpleSelectProps = SimpleSelectTypesModule.SimpleSelectProps;
export const SimpleSelect = ({
  options,
  value,
  onValueChange,
  placeholder = "Select an option",
  className,
  triggerClassName,
  disabled,
  withSearch = false,
  searchPlaceholder = "Search options...",
  mobileView = "keep",
  mobileViewSearch = false,
  drawerTitle = "Select an option",
}: SimpleSelectProps) => {
  const { isMobile } = useKitzeUI();
  const { isOpen, setIsOpen, close } = useControlledOpen({});
  const listId = React.useId();
  const selectedOption = options.find((option) => option.value === value);
  const triggerButton = (
    <SimpleSelectTrigger
      className={className}
      disabled={disabled}
      isOpen={isOpen}
      listId={listId}
      onClick={() => setIsOpen(!isOpen)}
      placeholder={placeholder}
      selectedOption={selectedOption}
      triggerClassName={triggerClassName}
      value={value}
    />
  );
  if (isMobile && mobileView === "native") {
    return (
      <SimpleSelectNative
        className={className}
        disabled={disabled}
        onValueChange={onValueChange}
        options={options}
        placeholder={placeholder}
        selectedOption={selectedOption}
        triggerClassName={triggerClassName}
        value={value}
      />
    );
  }
  if (isMobile && mobileView === "bottom-drawer") {
    return (
      <ResponsiveSelectBottomDrawerMenu
        options={options}
        value={value}
        onValueChange={(nextValue) => {
          onValueChange?.(nextValue);
          close();
        }}
        placeholder={placeholder}
        drawerTitle={drawerTitle}
        open={isOpen}
        onOpenChange={setIsOpen}
        searchPlaceholder={searchPlaceholder}
        showSearch={mobileViewSearch}
        triggerClassName={triggerClassName}
        className={className}
        disabled={disabled}
      >
        {triggerButton}
      </ResponsiveSelectBottomDrawerMenu>
    );
  }
  return (
    <SimpleSelectPopover
      className={className}
      listId={listId}
      onOpenChange={setIsOpen}
      onValueChange={onValueChange}
      open={isOpen}
      options={options}
      searchPlaceholder={searchPlaceholder}
      triggerButton={triggerButton}
      value={value}
      withSearch={withSearch}
    />
  );
};

import { ChevronsUpDown } from "lucide-react";
import * as React from "react";

import type { SelectOption } from "@/lib/types";
import { cn } from "@/lib/utils";

export const SimpleSelectNative = ({
  className,
  disabled,
  onValueChange,
  options,
  placeholder,
  selectedOption,
  triggerClassName,
  value,
}: {
  className?: string | undefined;
  disabled?: boolean | undefined;
  onValueChange?: ((value: string) => void) | undefined;
  options: SelectOption[];
  placeholder: string;
  selectedOption?: SelectOption | undefined;
  triggerClassName?: string | undefined;
  value?: string | undefined;
}) => (
  <div className={cn("relative w-full", className)}>
    <div
      className={cn(
        "border-input bg-background ring-offset-background placeholder:text-muted-foreground focus-within:ring-ring flex h-10 w-full items-center justify-between rounded-md border px-3 py-2 text-sm focus-within:ring-2 focus-within:ring-offset-2 focus-within:outline-none disabled:cursor-not-allowed disabled:opacity-50",
        triggerClassName,
        disabled && "cursor-not-allowed opacity-50"
      )}
      aria-disabled={disabled}
    >
      <span className="flex-grow truncate">
        {selectedOption?.icon &&
          React.createElement(selectedOption.icon, {
            className: "mr-2 h-4 w-4 inline",
          })}
        {selectedOption?.emoji && (
          <span className="mr-2">{selectedOption.emoji}</span>
        )}
        {value && selectedOption ? selectedOption.label || value : placeholder}
      </span>
      <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
    </div>
    <select
      value={value || ""}
      onChange={(event) => onValueChange?.(event.target.value)}
      disabled={disabled}
      className="absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0"
    >
      {placeholder && (
        <option value="" disabled hidden>
          {placeholder}
        </option>
      )}
      {options.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label || option.value}
        </option>
      ))}
    </select>
  </div>
);

import { Check } from "lucide-react";
import * as React from "react";

import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import type { SelectOption } from "@/lib/types";
import { cn } from "@/lib/utils";

export const SimpleSelectPopover = ({
  className,
  listId,
  onOpenChange,
  onValueChange,
  open,
  options,
  searchPlaceholder,
  triggerButton,
  value,
  withSearch,
}: {
  className?: string | undefined;
  listId: string;
  onOpenChange: (open: boolean) => void;
  onValueChange?: ((value: string) => void) | undefined;
  open: boolean;
  options: SelectOption[];
  searchPlaceholder: string;
  triggerButton: React.ReactElement;
  value?: string | undefined;
  withSearch: boolean;
}) => (
  <Popover open={open} onOpenChange={onOpenChange}>
    <PopoverTrigger render={triggerButton} />
    <PopoverContent
      className={cn("w-[var(--anchor-width)] p-0", className)}
      style={{
        minWidth: "var(--anchor-width)",
      }}
    >
      <Command>
        {withSearch && <CommandInput placeholder={searchPlaceholder} />}
        <CommandList id={listId}>
          <CommandEmpty>No options found.</CommandEmpty>
          <CommandGroup>
            {options.map((option) => (
              <CommandItem
                key={option.value}
                value={option.value}
                onSelect={(currentValue) => {
                  onValueChange?.(currentValue === value ? "" : currentValue);
                  onOpenChange(false);
                }}
              >
                <Check
                  className={cn(
                    "mr-2 h-4 w-4",
                    value === option.value ? "opacity-100" : "opacity-0"
                  )}
                />
                {option.icon &&
                  React.createElement(option.icon, {
                    className: "mr-2 h-4 w-4",
                  })}
                {option.emoji && <span className="mr-2">{option.emoji}</span>}
                {option.label}
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </Command>
    </PopoverContent>
  </Popover>
);

import { ChevronsUpDown } from "lucide-react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import type { SelectOption } from "@/lib/types";
import { cn } from "@/lib/utils";

export const SimpleSelectTrigger = ({
  className,
  disabled,
  isOpen,
  listId,
  onClick,
  placeholder,
  selectedOption,
  triggerClassName,
  value,
}: {
  className?: string | undefined;
  disabled?: boolean | undefined;
  isOpen: boolean;
  listId: string;
  onClick: () => void;
  placeholder: string;
  selectedOption?: SelectOption | undefined;
  triggerClassName?: string | undefined;
  value?: string | undefined;
}) => (
  <Button
    variant="outline"
    aria-haspopup="listbox"
    aria-expanded={isOpen}
    aria-controls={listId}
    className={cn("w-full justify-between", triggerClassName, className)}
    onClick={onClick}
    disabled={disabled}
  >
    {value && selectedOption ? (
      <span className="flex items-center truncate">
        {selectedOption.icon &&
          React.createElement(selectedOption.icon, {
            className: "mr-2 h-4 w-4",
          })}
        {selectedOption.emoji && (
          <span className="mr-2">{selectedOption.emoji}</span>
        )}
        {selectedOption.label || selectedOption.value}
      </span>
    ) : (
      placeholder
    )}
    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
  </Button>
);

import type { SelectOption } from "@/lib/types";

export type SelectMobileViewType = "keep" | "native" | "bottom-drawer";

export type SimpleSelectOption = SelectOption;

export interface SimpleSelectProps {
  options: SelectOption[];
  value?: string | undefined;
  onValueChange?: ((value: string) => void) | undefined;
  placeholder?: string | undefined;
  className?: string | undefined;
  triggerClassName?: string | undefined;
  disabled?: boolean | undefined;
  withSearch?: boolean | undefined;
  searchPlaceholder?: string | undefined;
  mobileView?: SelectMobileViewType | undefined;
  mobileViewSearch?: boolean | undefined;
  drawerTitle?: string | undefined;
}

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
